def get_raw_customer(email, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0093000" if __import__("os").path.isdir("./environment_mix/0093000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    # --- validation ---
    if not isinstance(email, str):
        return _err("VALIDATION_ERROR", "email must be a string")
    if email.strip() == "":
        return _err("VALIDATION_ERROR", "email is required and cannot be blank")
    e = email.strip()
    # pragmatic email format check
    if not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", e):
        return _err("VALIDATION_ERROR", "email is not a valid email address format", email=e)

    # --- record usage/audit for every call ---
    reqs = _load("requests.json")
    if not isinstance(reqs, list):
        reqs = []
    req_id = f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- perform lookup against real datastore (no CSV exists in schema) ---
    cust_data = _load("customers.json")
    customers = cust_data.get("rows") if isinstance(cust_data, dict) and isinstance(cust_data.get("rows"), list) else (cust_data if isinstance(cust_data, list) else [])
    found = None
    for c in customers:
        if isinstance(c, dict) and isinstance(c.get("email"), str) and c["email"].strip().lower() == e.lower():
            found = c
            break

    status = "ok"
    if found is None:
        status = "not_found"

    latency_ms = int((time.time() - _t0) * 1000)
    reqs.append({
        "request_id": req_id,
        "endpoint": "get_raw_customer",
        "timestamp": now,
        "status": status,
        "latency_ms": latency_ms
    })
    _save("requests.json", reqs)

    if found is None:
        return {"found": False, "email": e}
    # "raw-import" isn't available; return the stored record as the raw record we do have
    return {"found": True, "raw_record": found}

def total_mrr(tier=None, **_extra):
    import json, os, datetime, time
    from collections import defaultdict
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0093000" if __import__("os").path.isdir("./environment_mix/0093000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    allowed_tiers = {"enterprise", "pro", "starter"}
    if tier is not None:
        if not isinstance(tier, str):
            return _err("VALIDATION_ERROR", "tier must be a string when provided")
        if tier not in allowed_tiers:
            return _err("VALIDATION_ERROR", "tier must be one of enterprise, pro, starter", tier=tier)

    # --- compute ---
    cust_data = _load("customers.json")
    customers = cust_data.get("rows") if isinstance(cust_data, dict) and isinstance(cust_data.get("rows"), list) else (cust_data if isinstance(cust_data, list) else [])

    by_tier = defaultdict(int)
    total = 0
    customer_count = 0

    for c in customers:
        if not isinstance(c, dict):
            continue
        ctier = c.get("tier")
        mrr = c.get("mrr", 0)
        if not isinstance(mrr, int):
            # tolerate bad stored values by treating as 0; don't raise
            mrr = 0
        if ctier not in allowed_tiers:
            # ignore unknown stored tiers rather than erroring on read
            continue

        if tier is None:
            total += mrr
            by_tier[ctier] += mrr
            customer_count += 1
        else:
            if ctier == tier:
                total += mrr
                customer_count += 1

    # --- record usage/audit for every call ---
    reqs = _load("requests.json")
    if not isinstance(reqs, list):
        reqs = []
    req_id = f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    latency_ms = int((time.time() - _t0) * 1000)
    reqs.append({
        "request_id": req_id,
        "endpoint": "total_mrr",
        "timestamp": now,
        "status": "ok",
        "latency_ms": latency_ms,
        "tier": tier
    })
    _save("requests.json", reqs)

    if tier is not None:
        return {"tier": tier, "total_mrr": total, "customer_count": customer_count}
    return {"total_mrr": total, "by_tier": dict(by_tier), "customer_count": customer_count}
